class DataCache {
    std::string internal_str = "Data";
public:
    // Mutability: Allows caller to modify the internal string
    std::string& get_mutable_ref() {
        return internal_str;
    }

    // Efficiency: Avoids copying large objects for reading
    const std::string& get_const_ref() const {
        return internal_str;
    }
};

